class PayrollEmployee {int id;String name;double baseSalary;PayrollEmployee(int id,String name,double salary){this.id=id;this.name=name;baseSalary=salary;}double calculateSalary(int days){return 0;}void displayPaySlip(int days,double salary){System.out.printf("ID: %d%nName: %s%nDays Present: %d%nNet Salary: %.2f%n---------------------%n",id,name,days,salary);}}
class Manager extends PayrollEmployee {double bonus;Manager(int id,String name,double salary,double bonus){super(id,name,salary);this.bonus=bonus;}double calculateSalary(int days){return baseSalary/30*days+bonus;}}
class Developer extends PayrollEmployee {double allowance;Developer(int id,String name,double salary,double allowance){super(id,name,salary);this.allowance=allowance;}double calculateSalary(int days){return baseSalary/30*days+allowance;}}
class Intern extends PayrollEmployee {Intern(int id,String name,double stipend){super(id,name,stipend);}double calculateSalary(int days){return baseSalary/30*days;}}
public class Program8 {public static void main(String[] args){PayrollEmployee[] employees={new Manager(1,"Yeshe",60000,5000),new Developer(2,"Khushi",50000,3000),new Intern(3,"Ram",15000)};for(PayrollEmployee employee:employees)employee.displayPaySlip(25,employee.calculateSalary(25));}}
